import React, { useEffect, useState } from 'react';
import { Link } from 'react-router-dom';

function Navbar({ cart = [], onLogout }) {
    const [user, setUser] = useState(null); // State to store user data

    useEffect(() => {
        // Fetch user data from localStorage on component mount
        const storedUser = localStorage.getItem('user');
        if (storedUser) {
            setUser(JSON.parse(storedUser));
        }
    }, []);

    const handleLogout = () => {
        // Clear user data from localStorage and state
        localStorage.removeItem('user');
        localStorage.removeItem('token'); // If you're using tokens for authentication
        setUser(null);
        if (onLogout) onLogout(); // Optional: Call external logout logic
    };

    const cartCount = cart.reduce((count, item) => count + item.quantity, 0);

    return (
        <nav className="navbar bg-green-500 text-white py-4 px-6 flex justify-between items-center">
            <div className="logo text-2xl font-bold">
                <Link to="/" className="hover:text-gray-200">
                    MyShop
                </Link>
            </div>
            <div className="nav-links flex items-center space-x-6">
                <Link to="/products" className="hover:text-gray-200">
                    Products
                </Link>
                <Link to="/cart" className="hover:text-gray-200">
                    Cart ({cartCount})
                </Link>
                {user ? (
                    <div className="flex items-center space-x-4">
                        <Link to="/orders" className="hover:text-gray-200">
                            Orders
                        </Link>
                        <span className="user-profile font-medium">
                            Hello, {user.name}
                        </span>
                        <button
                            onClick={handleLogout}
                            className="bg-red-500 hover:bg-red-600 text-white py-1 px-4 rounded"
                        >
                            Logout
                        </button>
                    </div>
                ) : (
                    <Link to="/login" className="hover:text-gray-200">
                        Login
                    </Link>
                )}
            </div>
        </nav>
    );
}

export default Navbar;
